import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { action20InternalSchema, action20Schema, type Action20 } from "./action20.js";
import { statusConsentsStatusSchema, type StatusConsentsStatus } from "./status-consents-status.js";

export type ConsentsCancelResponse = {
  /**
   * A unique identifier that is used to identify and reference an instance of this resource. It is
   * generated by Global Payments to identify the transaction and must be used to action that
   * transaction in future.
   */
  id?: string;
  /** Global Payments generated time indicating when the consent was created in ISO-8601 format */
  timeCreated?: Date;
  /** Status of the consent */
  status?: StatusConsentsStatus;
  /** A unique identifier for the merchant set by Global Payments. */
  merchantId?: string;
  /** The merchant name of the account that sent the transfer. */
  merchantName?: string;
  /**
   * A unique identifier that is used to identify and reference an instance of the resource which
   * would would hold the permission and configuration to perform the action. Example TRA_uid
   */
  accountId?: string;
  /** A meaningful label that better identifies the GPAPI account. */
  accountName?: string;
  /** Merchant defined field to reference this consent request. */
  reference?: string;
  /** The reason specified by the merchant for the cancellation of consent. */
  description?: string;
  action?: Action20;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const consentsCancelResponseProperties: s.Shape<ConsentsCancelResponse> = {
  id: s.optional(s.string()),
  timeCreated: s.optional(s.dateTime()),
  status: s.optional(s.lazy(() => statusConsentsStatusSchema)),
  merchantId: s.optional(s.string()),
  merchantName: s.optional(s.string()),
  accountId: s.optional(s.string()),
  accountName: s.optional(s.string()),
  reference: s.optional(s.string()),
  description: s.optional(s.string()),
  action: s.optional(s.lazy(() => action20InternalSchema)),
  _keysMap: {
    timeCreated: "time_created",
    merchantId: "merchant_id",
    merchantName: "merchant_name",
    accountId: "account_id",
    accountName: "account_name",
  },
};

export const consentsCancelResponseInternalSchema: Schema<ConsentsCancelResponse> =
  s.object<ConsentsCancelResponse>(consentsCancelResponseProperties, { additionalProperties: s.json() });

export const consentsCancelResponseSchema: Schema<ConsentsCancelResponse> = s.lazySchema(() =>
  s.object<ConsentsCancelResponse>(
    {
      ...consentsCancelResponseProperties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      accountId: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      accountName: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      reference: s.optional(s.string().check(s.minLength(8), s.maxLength(50))),
      description: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      action: s.optional(s.lazy(() => action20Schema)),
    },
    { additionalProperties: s.json() },
  ),
);
